    var directions = { up: "1", down: "-1" };
    var units = { letter: true, word: true };

    var travel = travels[pick(travels, vars.travel, "standard")];
    var direction = directions[pick(directions, vars.direction, "up")];
    var unit = pick(units, vars.unit, "letter");

    document.querySelectorAll(".hf-bottom-up-letters").forEach((el) => {
      el.style.setProperty("--hf-letters-travel", travel);
      el.style.setProperty("--hf-letters-direction", direction);
      if (el.dataset.hfLettersReady === "1") return;
      const text = el.textContent || "";
      el.textContent = "";
      const parts = unit === "word" ? text.split(/(\s+)/) : Array.from(text);
      for (const part of parts) {
        if (part === "") continue;
        if (unit === "word" && /^\s+$/.test(part)) {
          el.appendChild(document.createTextNode(part));
          continue;
        }
        const span = document.createElement("span");
        span.className = "hf-bottom-up-letters-char";
        span.textContent = part === " " ? "\u00a0" : part;
        el.appendChild(span);
