            var countEase = gsap.parseEase("sine.inOut");
            var frameRows = [];

            for (var frame = 0; frame <= lastFrame; frame += 1) {
              var progress = frame / lastFrame;
              var easedProgress = countEase(progress);
              frameRows.push(formatValue(start + (end - start) * easedProgress));
