*,
          *::before,
          *::after {
            box-sizing: border-box;
          }

          #root {
            position: absolute;
            inset: 0;
            overflow: hidden;
            container-type: size;
            isolation: isolate;
            color: var(--fg, #f8fafc);
            font-family: var(--font-display, Inter, system-ui, sans-serif);
            pointer-events: none;
          }

          .hs-clip,
          .hs-stage {
            position: absolute;
            inset: 0;
            width: 100cqw;
            height: 100cqh;
          }

          .hs-clip {
            overflow: hidden;
          }

          .hs-stage {
            display: grid;
            place-items: center;
            will-change: transform;
          }

