            color: var(--hs-accent, #71f5a7);
          }
</style>

<template>
      <div id="root" data-composition-id="headline-slam" data-duration="3.5" data-fps="30">


        <div
          id="headline-slam-clip"
          class="hs-clip clip"
          data-start="0"
          data-duration="3.5"
          data-track-index="0"
        >
          <div class="hs-stage">
            <div class="hs-headline" role="heading" aria-level="1"></div>
          </div>
        </div>



