      paper: { bg: "#fafafa", fg: "#18181b" },
      accent: { bg: "var(--brand, #34d399)", fg: "#fff" },
    };
    var defaultWords = "COMPONENTS, PRIMITIVES, TRANSITIONS, AGENTS";

