.hf-tracking-in {
    opacity: 0;
    color: var(--hf-tracking-color, inherit);
    letter-spacing: calc(var(--hf-tracking-value, 0.28em) * var(--hf-tracking-reach, 1));
    transform: translateY(var(--hf-tracking-y, 8px));
    will-change: opacity, letter-spacing, transform;
